export function parsePositiveNumber(input: string): number {
  const text = String(input).trim()
  if (!/^\d+(\.\d+)?$/.test(text)) throw new RangeError('not a positive number')
  const n = Number(text)
  if (!Number.isFinite(n) || n <= 0) throw new RangeError('not a positive number')
  return n
}

