export function parseBool(s: string): boolean | null {
  const text = String(s).trim().toLowerCase()
  if (['true', '1', 'yes', 'on'].includes(text)) return true
  if (['false', '0', 'no', 'off'].includes(text)) return false
  return null
}

export function createStack<T>() {
  const items: T[] = []
  return {
    push(v: T): void {
      items.push(v)
    },
    pop(): T | null {
      return items.length > 0 ? items.pop()! : null
    },
    peek(): T | null {
      return items.length > 0 ? items[items.length - 1]! : null
    },
    size(): number {
      return items.length
    },
  }
}

export function createQueue<T>() {
  const items: T[] = []
  return {
    enqueue(v: T): void {
      items.push(v)
    },
    dequeue(): T | null {
      return items.length > 0 ? items.shift()! : null
    },
    size(): number {
      return items.length
    },
  }
}

export function createLRU(capacity: number) {
  const map = new Map<string, number>()
  return {
    get(key: string): number | null {
      if (!map.has(key)) return null
      const value = map.get(key)!
      map.delete(key)
      map.set(key, value)
      return value
    },
    set(key: string, value: number): void {
      if (map.has(key)) {
        map.delete(key)
      } else if (map.size >= capacity) {
        const oldest = map.keys().next().value
        if (oldest !== undefined) map.delete(oldest)
      }
      map.set(key, value)
    },
    size(): number {
      return map.size
    },
  }
}

